package com.cqu.drs.model;

import java.io.Serializable;
import java.time.LocalDateTime;

/**
 * A disaster reported by a member of the public. Central class of the DRS
 * domain model: reporting -&gt; assessment/prioritisation -&gt; coordinated response.
 * In DRS-Enhanced the identifier is generated by MySQL (AUTO_INCREMENT) when the
 * report is saved, and the report is digitally signed by the reporting user.
 */
public class DisasterReport implements Serializable {

    private static final long serialVersionUID = 1L;

    private int reportId;
    private DisasterType type;
    private String location;
    private String description;
    private String reporterName;
    private String reporterPhone;
    private SeverityLevel severity;
    private int priorityScore;
    private Status status;
    private LocalDateTime dateReported;
    private LocalDateTime lastUpdated;
    private String reportedBy;
    private String signature;
    private Boolean signatureValid;

    public DisasterReport() {
        this.status = Status.REPORTED;
        this.dateReported = LocalDateTime.now();
    }

    public DisasterReport(DisasterType type, String location, String description,
                          String reporterName, String reporterPhone) {
        this();
        this.type = type;
        this.location = location;
        this.description = description;
        this.reporterName = reporterName;
        this.reporterPhone = reporterPhone;
        this.severity = null;
        this.priorityScore = 0;
    }

    public int getReportId() {
        return reportId;
    }

    public void setReportId(int reportId) {
        this.reportId = reportId;
    }

    public DisasterType getType() {
        return type;
    }

    public void setType(DisasterType type) {
        this.type = type;
    }

    public String getLocation() {
        return location;
    }

    public void setLocation(String location) {
        this.location = location;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getReporterName() {
        return reporterName;
    }

    public void setReporterName(String reporterName) {
        this.reporterName = reporterName;
    }

    public String getReporterPhone() {
        return reporterPhone;
    }

    public void setReporterPhone(String reporterPhone) {
        this.reporterPhone = reporterPhone;
    }

    public SeverityLevel getSeverity() {
        return severity;
    }

    public void setSeverity(SeverityLevel severity) {
        this.severity = severity;
    }

    public int getPriorityScore() {
        return priorityScore;
    }

    public void setPriorityScore(int priorityScore) {
        this.priorityScore = priorityScore;
    }

    public Status getStatus() {
        return status;
    }

    public void setStatus(Status status) {
        this.status = status;
    }

    public LocalDateTime getDateReported() {
        return dateReported;
    }

    public void setDateReported(LocalDateTime dateReported) {
        this.dateReported = dateReported;
    }

    public LocalDateTime getLastUpdated() {
        return lastUpdated;
    }

    public void setLastUpdated(LocalDateTime lastUpdated) {
        this.lastUpdated = lastUpdated;
    }

    public String getReportedBy() {
        return reportedBy;
    }

    public void setReportedBy(String reportedBy) {
        this.reportedBy = reportedBy;
    }

    public String getSignature() {
        return signature;
    }

    public void setSignature(String signature) {
        this.signature = signature;
    }

    /** Result of the server's last signature check (null = not checked). */
    public Boolean getSignatureValid() {
        return signatureValid;
    }

    public void setSignatureValid(Boolean signatureValid) {
        this.signatureValid = signatureValid;
    }

    /** True when the report carries a digital signature (non-repudiation). */
    public boolean isSigned() {
        return signature != null && !signature.isEmpty();
    }

    /**
     * Canonical text that is digitally signed when the report is created.
     * Any later change to these fields invalidates the signature.
     */
    public String canonicalContent() {
        return type + "|" + location + "|" + description + "|" + reporterName + "|" + reportedBy;
    }

    /** Short label used in combo boxes, e.g. "#3 FIRE - Rockhampton CBD". */
    public String getSummary() {
        return "#" + reportId + " " + type + " - " + location;
    }

    @Override
    public String toString() {
        return "DisasterReport{id=" + reportId + ", type=" + type + ", location='" + location
                + "', severity=" + severity + ", priorityScore=" + priorityScore
                + ", status=" + status + ", reportedBy='" + reporterName + "'}";
    }
}
